const API='/api';
const state={user:JSON.parse(localStorage.getItem('tz-user')||'null'),token:localStorage.getItem('tz-token'),cart:JSON.parse(localStorage.getItem('tz-cart')||'{}'),settings:{},categories:[],products:[],adminTab:'overview',shop:{q:'',category:'',sort:'newest',page:1,pages:1,total:0}};
const pics={phone:'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?auto=format&fit=crop&w=700&q=80',laptop:'https://images.unsplash.com/photo-1496181133206-80ce9b88a853?auto=format&fit=crop&w=700&q=80',computer:'https://images.unsplash.com/photo-1587831990711-23ca6441447b?auto=format&fit=crop&w=700&q=80',monitor:'https://images.unsplash.com/photo-1527443224154-c4a3942d3acf?auto=format&fit=crop&w=700&q=80',headphones:'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=700&q=80',keyboard:'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=700&q=80',mouse:'https://images.unsplash.com/photo-1527814050087-3793815479db?auto=format&fit=crop&w=700&q=80',ssd:'https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?auto=format&fit=crop&w=700&q=80',charger:'https://images.unsplash.com/photo-1609592424689-0c6facaec7a4?auto=format&fit=crop&w=700&q=80'};
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return '$'+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});}
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token;const r=await fetch(API+path,{...opts,headers});let d;try{d=await r.json()}catch{d={message:'Server response error'}}if(!r.ok)throw Error(d.message||'Waxbaa qaldamay.');return d;}
function toast(m){const t=document.getElementById('toast');t.textContent=m;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function save(){localStorage.setItem('tz-cart',JSON.stringify(state.cart));if(state.user)localStorage.setItem('tz-user',JSON.stringify(state.user));}
function countCart(){return Object.values(state.cart).reduce((a,b)=>a+Number(b),0)}
function price(p){return p.discountPrice&&p.discountPrice<p.price?p.discountPrice:p.price}
function href(route){location.hash='/'+route}
function productImage(p){return p.images?.[0]||pics[({'Mobile Phones':'phone','Laptops':'laptop','Desktop Computers':'computer','Monitors':'monitor','Headphones':'headphones','Keyboards':'keyboard','Mice':'mouse','SSD':'ssd','Chargers':'charger'})[p.category]]||pics.computer}
function header(){const path=location.hash.slice(1)||'/';return `<div class="announcement">${esc(state.settings.description||'Alaab tayo leh, qiimo wanaagsan')} &nbsp; • &nbsp; <b>Gaarsiin degdeg ah gudaha Muqdisho</b></div><header class="header"><div class="wrap"><div class="head-main"><a class="logo" href="#/"><span class="brand-mark">T</span><span><strong>TekZone Somalia</strong><small>Technology for everyone</small></span></a><label class="searchbox"><span class="search-icon">⌕</span><input id="global-search" placeholder="Raadi telefoon, laptop ama qalab..." value="${esc(new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'')}"><button class="button small" onclick="searchNow()">Raadi</button></label><div class="head-actions"><a href="#/${state.user?'account':'login'}" class="head-action"><span class="ico">♙</span><span>${state.user?'Xisaabta':'Gal / Isdiiwaangeli'}</span></a><a href="#/wishlist" class="head-action"><span class="ico">♡</span><span>Jecel</span></a><a href="#/cart" class="head-action cart-pill"><span class="ico">🛒</span><span class="count">${countCart()}</span><span>Gaariga</span></a><button class="menu-toggle" onclick="document.querySelector('.nav').classList.toggle('open')">☰</button></div></div><nav class="nav">${[['/','Home'],['/shop','Shop'],['/shop?category=Mobile%20Phones','Mobiles'],['/shop?category=Laptops','Laptops'],['/shop?category=Desktop%20Computers','Computers'],['/shop?category=Computer%20Accessories','Accessories'],['/shop?sort=popular','Offers'],['/contact','Nala soo xiriir']].map(([u,t])=>`<a href="#${u}" class="${path===u?'active':''}">${t}</a>`).join('')}</nav></div></header>`}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><div><a class="logo" href="#/"><span class="brand-mark">T</span><span><strong>TekZone Somalia</strong><small>Technology for everyone</small></span></a><p>Alaab tayo leh, qiimo wanaagsan. Teknolojiyadda aad u baahan tahay waxaad ka helaysaa halkaan.</p></div><div><h4>Dalbo</h4><p><a href="#/shop">Dhammaan alaabta</a><br><a href="#/shop?category=Mobile%20Phones">Telefoonno</a><br><a href="#/shop?category=Laptops">Laptops</a><br><a href="#/shop?category=Computer%20Accessories">Qalabka kombiyuutarka</a></p></div><div><h4>Macluumaad</h4><p><a href="#/about">Nagu saabsan</a><br><a href="#/contact">Nala soo xiriir</a><br><a href="#/orders">Dalabyadayda</a></p></div><div><h4>Nala soo xiriir</h4><p>☎ ${esc(state.settings.phone||'+252 61 0000000')}<br>✉ ${esc(state.settings.email||'hello@tekzone.so')}<br>⌖ ${esc(state.settings.address||'Mogadishu, Somalia')}</p></div></div><div class="footer-bottom">© ${new Date().getFullYear()} TekZone Somalia. Xuquuqdu way dhowran tahay. <span style="float:right">Qiimaha: USD</span></div></div></footer><div class="mobile-bottom"><a href="#/"><i>⌂</i>Home</a><a href="#/shop"><i>▦</i>Shop</a><a href="#/wishlist"><i>♡</i>Jecel</a><a href="#/account"><i>♙</i>Xisaab</a><a href="#/cart"><i>🛒</i>Gaariga (${countCart()})</a></div>`}
function productCard(p){return `<article class="product-card"><div class="product-img"><a href="#/product/${p._id}"><img loading="lazy" src="${esc(productImage(p))}" alt="${esc(p.name)}" onerror="this.src='${pics.computer}'"></a>${p.discountPrice?'<span class="badge">QIIMO DHIMIS</span>':p.newArrival?'<span class="badge">CUSUB</span>':''}<button class="wishlist-btn" title="Ku dar kuwa la jecel yahay" onclick="toggleWish('${p._id}')">♡</button></div><div class="product-info"><span class="product-brand">${esc(p.brand||'TekZone')}</span><a href="#/product/${p._id}"><h3>${esc(p.name)}</h3></a><div class="rating">★★★★★ <span>(${p.reviewsCount||0})</span></div><div class="prices"><span class="price">${money(price(p))}</span>${p.discountPrice?`<del class="old-price">${money(p.price)}</del>`:''}</div><span class="stock ${p.stock<=5?'low':''}">${p.stock>5?'✓ Waa la heli karaa':p.stock>0?'⚠ Wax yar baa haray':'Out of Stock'}</span><div class="product-actions"><button class="button small" ${p.stock<1?'disabled':''} onclick="addCart('${p._id}')">Ku dar Gaariga</button></div></div></article>`}
function sectionProducts(title,subtitle,products,link='/shop'){return `<section class="section"><div class="wrap"><div class="section-head"><div><h2>${title}</h2><p>${subtitle}</p></div><a class="text-link" href="#${link}">Dhammaan →</a></div><div class="product-grid">${products.length?products.map(productCard).join(''):emptyInline('Alaab lama helin')}</div></div></section>`}
function emptyInline(s){return `<div class="muted" style="padding:25px 0">${s}</div>`}
function home(){return `<main><section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><span class="eyebrow">TEKNOLOJIYADDA CUSUB • MOGADISHU</span><h1>Teknolojiyaddaada halkaan ka hel.</h1><p>Ku soo dhawoow TekZone Somalia. Soo hel telefoonno, laptops iyo qalab tayo leh oo qiimo wanaagsan leh.</p><a class="button" href="#/shop">Dalbo hadda <span>→</span></a> &nbsp; <a class="text-link" href="#/about">Wax badan naga baro</a></div><div class="hero-image"><img src="${pics.laptop}" alt="Laptop casri ah"></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><h2>Ku dukaamayso qaybta aad rabto</h2><p>Qalabka teknolojiyadda oo dhan, hal meel.</p></div><a class="text-link" href="#/shop">Dhammaan qaybaha →</a></div><div class="category-grid">${[['Mobile Phones','Telefoonno',pics.phone],['Laptops','Laptops',pics.laptop],['Desktop Computers','Kombiyuutarro',pics.computer],['Monitors','Shaashado',pics.monitor],['Headphones','Sameecado',pics.headphones],['Computer Accessories','Qalab kale',pics.keyboard],['Printers','Printerro','https://images.unsplash.com/photo-1613395450289-e560907d9308?auto=format&fit=crop&w=700&q=80'],['HDD','Hard drive','https://images.unsplash.com/photo-1597872200969-2b65d56bd16b?auto=format&fit=crop&w=700&q=80'],['USB Drives','Flash drives','https://images.unsplash.com/photo-1493946947703-a0e68b050bee?auto=format&fit=crop&w=700&q=80']].map(([c,t,i])=>`<a class="category-card" href="#/shop?category=${encodeURIComponent(c)}"><strong>${t}</strong><small>Alaab tayo leh</small><img loading="lazy" src="${i}" alt=""></a>`).join('')}</div></div></section><section class="section soft"><div class="wrap"><div class="promo"><div><span class="eyebrow">QIIMO DHIMIS GAAR AH</span><h2>Kor u qaad qalabkaaga maanta.</h2><p>Hel qiimo wanaagsan iyo adeeg lagu kalsoonaan karo.</p><a class="button" href="#/shop?sort=popular">Eeg dalabyada →</a></div></div></div></section>${sectionProducts('Alaabta ugu caansan','Waxyaabaha macaamiisheennu jecel yihiin',state.products.filter(p=>p.bestSeller||p.featured).slice(0,4))}${sectionProducts('Alaab cusub','Soo galitaankii ugu dambeeyay',state.products.filter(p=>p.newArrival).slice(0,4))}<section class="section soft"><div class="wrap"><div class="section-head"><div><h2>Maxaad TekZone u dooranaysaa?</h2><p>Adeeg kuu fudud, kalsooni aad ku tiirsanaan karto.</p></div></div><div class="benefits"><div class="benefit"><i>✓</i><strong>Alaab la hubo</strong><p>Waxaan kuu soo xulnaa alaab tayo iyo asal leh.</p></div><div class="benefit"><i>🚚</i><strong>Gaarsiin degdeg ah</strong><p>Dalabkaaga si ammaan ah ayaan kuugu keenaynaa.</p></div><div class="benefit"><i>☏</i><strong>Taageero kuu dhow</strong><p>Nala soo xiriir, diyaar ayaan kuu nahay.</p></div><div class="benefit"><i>↺</i><strong>Dalab fudud</strong><p>Si fudud u dooro, noo sheeg meesha aad joogto.</p></div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><h2>Waxa ay macaamiishu leeyihiin</h2><p>Kalsoonida macaamiisheennu waa mudnaantayada.</p></div></div><div class="review-grid"><div class="review-card"><div class="rating">★★★★★</div><p>“Dalabkayga si dhakhso leh ayuu ku yimid. Laptop-ka aan doortay waa mid tayo fiican leh.”</p><strong>— Sahra, Muqdisho</strong></div><div class="review-card"><div class="rating">★★★★★</div><p>“Adeeg wanaagsan iyo qiimo macquul ah. Mar kale ayaan wax ka iibsan doonaa.”</p><strong>— Maxamed, Hargeysa</strong></div><div class="review-card"><div class="rating">★★★★★</div><p>“Waxaan helay telefoonkii aan rabay, si fiicanna ayaa la iila socodsiiyay.”</p><strong>— Ayaan, Muqdisho</strong></div></div></div></section></main>`}
function pageTitle(title,sub='TekZone Somalia'){return `<div class="page-title"><div class="wrap"><div class="crumb"><a href="#/">Home</a> / ${title}</div><h1>${title}</h1><div class="muted">${sub}</div></div></div>`}
function shopPage(){const cats=state.categories.length?state.categories.map(c=>c.name):['Mobile Phones','Laptops','Desktop Computers','Monitors','Computer Accessories','Mobile Accessories'];const brands=[...new Set(state.products.map(p=>p.brand).filter(Boolean))].sort();return `${pageTitle('Shop','Soo hel alaabta kuu habboon')}<div class="wrap shop-layout"><aside class="filters" id="filters"><h3>Shaandhee alaabta</h3><div class="filter-group"><strong>Qaybta</strong>${cats.map(c=>`<label><input type="radio" name="category" ${state.shop.category===c?'checked':''} onchange="shopFilter('category','${esc(c)}')">${esc(c)}</label>`).join('')}<label><input type="radio" name="category" ${!state.shop.category?'checked':''} onchange="shopFilter('category','')">Dhammaan</label></div><div class="filter-group"><strong>Summad</strong><select class="admin-select" onchange="shopFilter('brand',this.value)"><option value="">Dhammaan summadaha</option>${brands.map(b=>`<option ${state.shop.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="filter-group"><strong>Qiimaha (USD)</strong><div style="display:flex;gap:5px"><input type="number" id="min-price" placeholder="Min" value="${esc(state.shop.min||'')}"><input type="number" id="max-price" placeholder="Max" value="${esc(state.shop.max||'')}"></div><button class="button small" style="margin-top:8px" onclick="applyPrice()">Codso</button></div><div class="filter-group"><strong>Qiimeynta ugu yar</strong><select class="admin-select" onchange="shopFilter('minRating',this.value)"><option value="">Dhammaan</option><option value="4" ${state.shop.minRating==='4'?'selected':''}>4 xiddig iyo ka badan</option><option value="3" ${state.shop.minRating==='3'?'selected':''}>3 xiddig iyo ka badan</option></select></div><div class="filter-group"><strong>Helitaanka</strong><label><input type="checkbox" ${state.shop.availability==='in'?'checked':''} onchange="shopFilter('availability',this.checked?'in':'')">Kuwa bakhaarka yaal</label></div></aside><div><div class="filter-toolbar"><div><button class="button light small" onclick="document.getElementById('filters').classList.toggle('show')">☷ Shaandhee</button> <span class="muted">${state.shop.total} alaab</span></div><select onchange="shopFilter('sort',this.value)"><option value="newest" ${state.shop.sort==='newest'?'selected':''}>Ugu cusub</option><option value="price-asc" ${state.shop.sort==='price-asc'?'selected':''}>Qiimo: hoose ilaa sare</option><option value="price-desc" ${state.shop.sort==='price-desc'?'selected':''}>Qiimo: sare ilaa hoose</option><option value="popular" ${state.shop.sort==='popular'?'selected':''}>Ugu caansan</option><option value="rating" ${state.shop.sort==='rating'?'selected':''}>Qiimeynta sare</option></select></div><div class="product-grid shop-products">${state.products.length?state.products.map(productCard).join(''):`<div class="empty" style="grid-column:1/-1"><div class="empty-icon">⌕</div><h2>Alaab lama helin</h2><p>Isku day raadis ama shaandho kale.</p></div>`}</div>${state.shop.pages>1?`<div style="display:flex;justify-content:center;align-items:center;gap:12px;padding:25px"><button class="button light small" ${state.shop.page<=1?'disabled':''} onclick="shopFilter('page',${state.shop.page-1})">← Hore</button><span class="muted">Bogga ${state.shop.page} / ${state.shop.pages}</span><button class="button light small" ${state.shop.page>=state.shop.pages?'disabled':''} onclick="shopFilter('page',${state.shop.page+1})">Xiga →</button></div>`:''}</div></div>`}
function productPage(id){return `<div id="product-detail" class="wrap"><div class="empty">Waa la soo rarayaa...</div></div>`}
function cartPage(){const ids=Object.keys(state.cart);const items=state.products.filter(p=>ids.includes(p._id));if(!items.length)return `${pageTitle('Gaariga wax iibsiga')}<div class="wrap empty"><div class="empty-icon">🛒</div><h2>Gaarigaagu waa madhan yahay</h2><p>Ku dar alaabta aad rabto inaad dalbato.</p><a class="button" href="#/shop">Bilaaw wax iibsiga</a></div>`;const sub=items.reduce((s,p)=>s+price(p)*state.cart[p._id],0);return `${pageTitle('Gaariga wax iibsiga',`${countCart()} alaab ayaa gaariga ku jirta`)}<div class="wrap cart-layout"><div class="cart-list">${items.map(p=>`<div class="cart-row"><img src="${esc(productImage(p))}" alt=""><div><a href="#/product/${p._id}"><h3>${esc(p.name)}</h3></a><span class="muted">${money(price(p))}</span><br><button class="text-link" onclick="removeCart('${p._id}')">Ka saar</button></div><div class="quantity"><button onclick="qty('${p._id}',-1)">−</button><span>${state.cart[p._id]}</span><button onclick="qty('${p._id}',1)">+</button></div><strong>${money(price(p)*state.cart[p._id])}</strong></div>`).join('')}</div><aside class="summary"><h3>Wadarta dalabka</h3><div class="sum-row"><span>Wadarta alaabta</span><b>${money(sub)}</b></div><div class="sum-row"><span>Gaarsiin</span><b>${money(state.settings.deliveryFee||3)}</b></div><div class="sum-row total"><span>Wadarta guud</span><b>${money(sub+Number(state.settings.deliveryFee||3))}</b></div><a class="button" href="#/checkout">U gudub bixinta →</a><a class="button light" href="#/shop">Sii wad wax iibsiga</a></aside></div>`}
function checkoutPage(){if(!countCart())return cartPage();if(!state.token||state.user?.role!=='customer'){sessionStorage.setItem('tz-after-auth','checkout');return `${pageTitle('Gal akoonkaaga','Si aad dalab u xaqiijiso')}<div class="wrap empty"><div class="empty-icon">?</div><h2>Dalabku wuxuu u baahan yahay akoon macaamiil</h2><p>Gal ama sameyso akoon; alaabta gaarigaaga waa kuu sii kaydsan tahay.</p><a class="button" href="#/login">Gal akoonka</a> &nbsp; <a class="button light" href="#/register">Sameyso akoon</a></div>`}return `${pageTitle('Xaqiiji dalabka','Buuxi xogta gaarsiinta')}<div class="wrap checkout-layout"><form id="checkout-form" class="panel"><h3>Xogta gaarsiinta</h3><div class="form-grid"><div class="field"><label>Magaca oo buuxa *</label><input name="name" required value="${esc(state.user?.name||'')}"></div><div class="field"><label>Telefoonka *</label><input name="phone" required value="${esc(state.user?.phone||'')}"></div><div class="field"><label>Email</label><input name="email" type="email" value="${esc(state.user?.email||'')}"></div><div class="field"><label>Magaalada *</label><input name="city" required></div><div class="field"><label>Degmada</label><input name="district"></div><div class="field full"><label>Cinwaanka gaarsiinta *</label><input name="address" required placeholder="Xaafadda, jidka iyo tilmaamo kale"></div><div class="field"><label>Habka lacag bixinta</label><select name="paymentMethod"><option value="cod">Lacag marka la keeno</option><option value="manual">Lacag bixin / nala soo xiriir</option></select></div><div class="field full"><label>Faahfaahin dheeraad ah</label><textarea name="notes"></textarea></div></div><button class="button" style="margin-top:15px">Xaqiiji dalabka →</button></form><aside class="summary"><h3>Alaabtaada</h3>${Object.entries(state.cart).map(([id,q])=>{const p=state.products.find(x=>x._id===id);return p?`<div class="sum-row"><span>${esc(p.name)} × ${q}</span><b>${money(price(p)*q)}</b></div>`:''}).join('')}<div class="sum-row"><span>Gaarsiin</span><b>${money(state.settings.deliveryFee||3)}</b></div><div class="sum-row total"><span>Wadarta guud</span><b>${money(Object.entries(state.cart).reduce((s,[id,q])=>s+(price(state.products.find(p=>p._id===id)||{price:0})*q),Number(state.settings.deliveryFee||3)))}</b></div></aside></div>`}
function authPage(register=false){return `<div class="wrap"><form id="auth-form" class="auth-box"><span class="eyebrow">TEKZONE SOMALIA</span><h1>${register?'Abuur akoonkaaga':'Ku soo dhawoow'}</h1><p>${register?'Ku biir macaamiisha TekZone.':'Gal si aad u maamusho dalabyadaada.'}</p>${register?`<div class="field"><label>Magaca oo buuxa</label><input name="name" required></div><div class="field"><label>Telefoonka</label><input name="phone" required></div><div class="field"><label>Email</label><input name="email" type="email"></div>`:`<div class="field"><label>Email ama telefoon</label><input name="identity" required autocomplete="username"></div>`}<div class="field"><label>Erayga sirta ah</label><input id="auth-password" name="password" type="password" ${register?'minlength="8"':''} required autocomplete="${register?'new-password':'current-password'}">${register?'':'<label style="display:flex;align-items:center;gap:7px;margin-top:8px;font-weight:500;color:#667085"><input type="checkbox" onchange="document.getElementById(\'auth-password\').type=this.checked?\'text\':\'password\'"> Muuji erayga sirta ah</label>'}</div>${register?'<div class="field"><label>Xaqiiji erayga sirta ah</label><input name="confirm" type="password" minlength="8" required></div>':''}<button class="button" style="width:100%;margin:7px 0">${register?'Isdiiwaangeli':'Gal akoonka'}</button><p style="text-align:center;margin:10px 0 0">${register?'Hore akoon ma u leedahay?':'Akoon ma lihid?'} <a class="text-link" href="#/${register?'login':'register'}">${register?'Gal':'Abuur akoon'}</a></p></form></div>`}
function accountPage(){if(!state.user)return authPage(false);return `${pageTitle('Xisaabtayda')}<div class="wrap" style="padding:30px 0;max-width:850px"><div class="panel"><h2>Ku soo dhawoow, ${esc(state.user.name)}</h2><p class="muted">${esc(state.user.email||'')} • ${esc(state.user.phone||'')}</p><div style="display:flex;gap:10px;flex-wrap:wrap"><a class="button" href="#/orders">Eeg dalabyadayda</a><a class="button light" href="#/wishlist">Waxyaabaha aan jeclahay</a>${state.user.role==='admin'?'<a class="button dark" href="#/admin">Maamulka</a>':''}<button class="button light" onclick="logout()">Ka bax</button></div></div><form id="profile-form" class="panel" style="margin-top:15px"><h3>Xogta akoonka</h3><div class="form-grid"><div class="field"><label>Magaca</label><input name="name" required value="${esc(state.user.name)}"></div><div class="field"><label>Telefoonka</label><input name="phone" required value="${esc(state.user.phone||'')}"></div><div class="field full"><label>Cinwaanka</label><input name="address" value="${esc(state.user.address||'')}"></div></div><button class="button" style="margin-top:12px">Kaydi xogta</button></form></div>`}
function contactPage(){return `${pageTitle('Nala soo xiriir','Waxaan diyaar u nahay inaan ku caawinno')}<div class="wrap" style="padding:32px 0;display:grid;grid-template-columns:1fr 1fr;gap:24px"><div class="panel"><h2>La hadal TekZone</h2><p class="muted">Su'aal ma qabtaa? Nala soo xiriir telefoon ama email.</p><p>☎ ${esc(state.settings.phone||'')}</p><p>✉ ${esc(state.settings.email||'')}</p><p>⌖ ${esc(state.settings.address||'')}</p><a class="button" href="https://wa.me/${String(state.settings.whatsapp||'').replace(/\D/g,'')}" target="_blank">WhatsApp nagula hadal</a></div><form id="contact-form" class="panel"><h3>Farriin noo reeb</h3><div class="field"><label>Magaca</label><input name="name" required></div><div class="field" style="margin-top:12px"><label>Email ama telefoon</label><input name="contact" required></div><div class="field" style="margin-top:12px"><label>Farriintaada</label><textarea name="message" required></textarea></div><button class="button" style="margin-top:12px">Dir farriinta</button></form></div>`}
function aboutPage(){return `${pageTitle('Nagu saabsan','TekZone Somalia')}<div class="wrap" style="padding:45px 0;max-width:850px"><span class="eyebrow">KU SOO DHAWOOW TEKZONE</span><h2 style="font:800 31px Manrope">Teknolojiyadda qof walba u dhow.</h2><p class="detail-copy">${esc(state.settings.description||'TekZone Somalia waa dukaan teknolojiyadeed oo bixiya telefoonno, laptops, kombiyuutarro iyo qalab tayo leh oo loogu talagalay macaamiisha Soomaaliyeed. Himiladeennu waa inaan kuu fududeyno helitaanka qalabka aad u baahan tahay, annagoo ku siinayna adeeg daacad ah iyo qiimo wanaagsan.')}</p><p class="detail-copy">Waxaan aaminsanahay in adeeg wanaagsan uu ka bilaabmo dhageysiga macaamiisha. Kooxdayadu waxay diyaar u tahay inay kaa caawiso doorashada alaabta saxda ah iyo gaarsiinta dalabkaaga.</p><a class="button" href="#/shop">Eeg alaabta</a></div>`}
function ordersPage(){return `<div id="orders-view">${pageTitle('Dalabyadayda')}<div class="wrap empty">Waa la soo rarayaa...</div></div>`}
function wishlistPage(){return `<div id="wishlist-view">${pageTitle('Waxyaabaha aan jeclahay')}<div class="wrap empty">Waa la soo rarayaa...</div></div>`}
function successPage(){const o=JSON.parse(sessionStorage.getItem('tz-last-order')||'null');return `${pageTitle('Dalabka waa la xaqiijiyay')}<div class="wrap empty"><div class="empty-icon">✓</div><span class="eyebrow">MAHADSANID</span><h2>Dalabkaaga waan helnay!</h2>${o?`<p>Lambarka dalabkaaga: <b>${esc(o.orderNumber)}</b></p><p>Wadarta: <b>${money(o.total)}</b> • Xaalad: <span class="status">${esc(o.status)}</span></p>`:''}<p>Kooxdayadu way kula soo xiriiri doontaa si ay u xaqiijiso dalabka.</p><a class="button" href="#/orders">Eeg dalabyada</a> <a class="button light" href="#/shop">Sii wad</a></div>`}
function adminPage(){if(state.user?.role!=='admin')return authPage(false);return `<div class="admin-shell"><div class="admin-top"><a href="#/" class="logo"><span class="brand-mark">T</span><strong>TekZone <span class="muted">Admin</span></strong></a><div><a class="text-link" href="#/">Dukaanka</a> &nbsp; <button class="button light small" onclick="logout()">Ka bax</button></div></div><div class="admin-layout"><aside class="admin-side">${[['overview','Guudmar'],['products','Alaabta'],['categories','Qaybaha'],['orders','Dalabyada'],['customers','Macaamiisha'],['inventory','Bakhaarka'],['reviews','Qiimeynta'],['settings','Dejinta']].map(([k,v])=>`<a class="${state.adminTab===k?'active':''}" href="#/admin/${k}">${v}</a>`).join('')}</aside><main class="admin-main" id="admin-content"><div class="empty">Waa la soo rarayaa...</div></main></div></div>`}
function notFound(){return `${pageTitle('Bogga lama helin')}<div class="wrap empty"><div class="empty-icon">404</div><h2>Boggan lama helin</h2><p>Raadintaadu meel kale ayay u baahan tahay.</p><a class="button" href="#/">Ku noqo bogga hore</a></div>`}
async function render(){const hash=location.hash.slice(1)||'/';const [route,query='']=hash.split('?');const params=new URLSearchParams(query);document.title='TekZone Somalia | '+(route==='/'?'Teknolojiyaddaada halkaan ka hel':route.slice(1));if(route.startsWith('/admin'))state.adminTab=route.split('/')[2]||'overview';if(route==='/shop'){state.shop={...state.shop,q:params.get('q')||'',category:params.get('category')||'',sort:params.get('sort')||state.shop.sort,page:Number(params.get('page'))||1};await loadProducts();}const renderMap={'/':home,'/shop':shopPage,'/cart':cartPage,'/checkout':checkoutPage,'/login':()=>authPage(false),'/register':()=>authPage(true),'/account':accountPage,'/contact':contactPage,'/about':aboutPage,'/orders':ordersPage,'/wishlist':wishlistPage,'/success':successPage};let body;if(route.startsWith('/product/'))body=productPage(route.split('/')[2]);else if(route.startsWith('/admin'))body=adminPage();else body=(renderMap[route]||notFound)();document.getElementById('app').innerHTML=route.startsWith('/admin')?body:header()+body+footer();wireForms(route);if(route.startsWith('/product/'))loadProduct(route.split('/')[2]);if(route==='/orders')loadOrders();if(route==='/wishlist')loadWishlist();if(route.startsWith('/admin'))loadAdmin(state.adminTab);}
async function loadProducts(){try{const q=new URLSearchParams({sort:state.shop.sort||'newest',page:state.shop.page||1,limit:24});if(state.shop.q)q.set('q',state.shop.q);if(state.shop.category)q.set('category',state.shop.category);if(state.shop.availability)q.set('availability',state.shop.availability);if(state.shop.min)q.set('min',state.shop.min);if(state.shop.max)q.set('max',state.shop.max);if(state.shop.minRating)q.set('minRating',state.shop.minRating);if(state.shop.brand)q.set('brand',state.shop.brand);const d=await api('/products?'+q);state.products=d.items;state.shop.pages=d.pages;state.shop.total=d.total;}catch(e){state.products=[];toast(e.message)}}
function searchNow(){const q=document.getElementById('global-search').value.trim();href('shop?q='+encodeURIComponent(q))}
function shopFilter(k,v){state.shop[k]=v;state.shop.page=1;href('shop?'+new URLSearchParams(Object.entries(state.shop).filter(([,x])=>x)).toString())}
function applyPrice(){state.shop.min=document.getElementById('min-price').value;state.shop.max=document.getElementById('max-price').value;shopFilter('page',1)}
function addCart(id){const p=state.products.find(x=>x._id===id);if(!p)return toast('Alaabta waa la soo rarayaa.');if((state.cart[id]||0)>=p.stock)return toast('Bakhaarka kuma filna.');state.cart[id]=(state.cart[id]||0)+1;save();toast('Alaabta gaariga ayaa lagu daray.');render()}
function qty(id,step){const p=state.products.find(x=>x._id===id);const next=(state.cart[id]||0)+step;if(next<1)delete state.cart[id];else if(next>p.stock)toast('Bakhaarka kuma filna.');else state.cart[id]=next;save();render()}
function removeCart(id){delete state.cart[id];save();render()}
async function toggleWish(id){if(!state.token){toast('Fadlan gal si aad u isticmaasho liiska jecel.');return href('login')}try{const exists=(await api('/wishlist')).some(x=>x._id===id);await api('/wishlist/'+id,{method:exists?'DELETE':'POST'});toast(exists?'Waa laga saaray liiska.':'Liiska jecel ayaa lagu daray.')}catch(e){toast(e.message)}}
function logout(){state.token=null;state.user=null;localStorage.removeItem('tz-token');localStorage.removeItem('tz-user');toast('Waad ka baxday.');href('/')}
async function loadProduct(id){const root=document.getElementById('product-detail');try{const {product:p,reviews}=await api('/products/'+id);state.currentProduct=p;if(!state.products.some(x=>x._id===p._id))state.products.push(p);root.innerHTML=`<div class="detail"><div><div class="gallery-main"><img src="${esc(productImage(p))}" alt="${esc(p.name)}"></div></div><div><div class="crumb"><a href="#/">Home</a> / <a href="#/shop">Shop</a> / ${esc(p.category)}</div><span class="product-brand">${esc(p.brand)}</span><h1>${esc(p.name)}</h1><div class="rating">★★★★★ <span>${Number(p.rating||0).toFixed(1)} (${p.reviewsCount||0} qiimeyn)</span></div><div class="detail-price">${money(price(p))}${p.discountPrice?`<del>${money(p.price)}</del>`:''}</div><div class="stock ${p.stock<=5?'low':''}">${p.stock>0?'✓ Bakhaarka: '+p.stock:'Out of Stock'}</div><p class="detail-copy">${esc(p.description||'Alaab tayo leh oo laga heli karo TekZone Somalia.')}</p><div class="buy-row"><div class="quantity"><button onclick="detailQty(-1)">−</button><span id="detail-qty">1</span><button onclick="detailQty(1)">+</button></div><button class="button" ${p.stock<1?'disabled':''} onclick="addDetailCart('${p._id}',false)">Ku dar Gaariga</button><button class="button dark" ${p.stock<1?'disabled':''} onclick="addDetailCart('${p._id}',true)">Iibso Hadda</button></div><button class="button light small" onclick="toggleWish('${p._id}')">♡ Ku dar liiska jecel</button><div class="specs"><h3>Faahfaahinta</h3><div class="spec-row"><b>SKU</b><span>${esc(p.sku)}</span></div><div class="spec-row"><b>Qaybta</b><span>${esc(p.category)}</span></div>${[...(p.specifications instanceof Object?Object.entries(p.specifications):[])].map(([k,v])=>`<div class="spec-row"><b>${esc(k)}</b><span>${esc(v)}</span></div>`).join('')}</div></div></div><section class="section"><h2>Qiimeynta macaamiisha</h2>${state.user?`<form id="review-form" class="panel" style="max-width:560px;margin:15px 0"><input type="hidden" name="product" value="${p._id}"><div class="field"><label>Qiimeyn (1–5)</label><select name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="field"><label>Faallo</label><textarea name="comment"></textarea></div><button class="button" style="margin-top:10px">Dir qiimeyn</button></form>`:''}${reviews.length?reviews.map(r=>`<div class="review-card" style="margin:8px 0"><b>${esc(r.user?.name||'Macaamiil')}</b> <span class="rating">${'★'.repeat(r.rating)}</span><p>${esc(r.comment)}</p></div>`).join(''):'<p class="muted">Weli wax qiimeyn ah ma jiraan.</p>'}</section>${sectionProducts('Alaab kale oo kuu habboon','Waxyaabo la mid ah',state.products.filter(x=>x._id!==p._id&&x.category===p.category).slice(0,4))}`;wireForms('/product');window.detailCount=1;}catch(e){root.innerHTML=`<div class="empty"><h2>${esc(e.message)}</h2><a class="button" href="#/shop">Ku noqo Shop</a></div>`}}
function detailQty(d){window.detailCount=Math.max(1,(window.detailCount||1)+d);document.getElementById('detail-qty').textContent=window.detailCount}
function addDetailCart(id,buy){const n=window.detailCount||1,p=state.products.find(x=>x._id===id)||state.currentProduct;if(!p||n+(state.cart[id]||0)>p.stock)return toast('Tirada aad dooratay bakhaarka kuma filna.');state.cart[id]=(state.cart[id]||0)+n;save();buy?href('checkout'): (toast('Gaariga waa lagu daray.'),render())}
function wireForms(route){const authForm=document.getElementById('auth-form');authForm?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(authForm));try{if(route==='/register'&&d.password!==d.confirm)throw Error('Erayada sirta ahi isma laha.');const result=await api('/auth/'+(route==='/register'?'register':'login'),{method:'POST',body:JSON.stringify(route==='/register'?d:{identity:d.identity,password:d.password})});state.token=result.token;state.user=result.user;localStorage.setItem('tz-token',result.token);localStorage.setItem('tz-user',JSON.stringify(result.user));toast('Waad ku guulaysatay inaad gasho.');const resume=sessionStorage.getItem('tz-after-auth');sessionStorage.removeItem('tz-after-auth');href(result.user.role==='admin'?'/admin':resume==='checkout'?'/checkout':'/account')}catch(err){toast(err.message)}});
const checkout=document.getElementById('checkout-form');checkout?.addEventListener('submit',async e=>{e.preventDefault();const info=Object.fromEntries(new FormData(checkout));const items=Object.entries(state.cart).map(([product,quantity])=>({product,quantity}));try{const order=await api('/orders',{method:'POST',body:JSON.stringify({items,customerInfo:info,paymentMethod:info.paymentMethod})});state.cart={};save();sessionStorage.setItem('tz-last-order',JSON.stringify(order));href('success')}catch(err){toast(err.message)}});
const profile=document.getElementById('profile-form');profile?.addEventListener('submit',async e=>{e.preventDefault();try{state.user=await api('/auth/me',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(profile)))});save();toast('Xogta waa la kaydiyay.');render()}catch(err){toast(err.message)}});
const contact=document.getElementById('contact-form');contact?.addEventListener('submit',e=>{e.preventDefault();const d=Object.fromEntries(new FormData(contact));const phone=String(state.settings.whatsapp||'').replace(/\D/g,'');if(!phone)return toast('Fadlan nagala soo xiriir telefoonka ku qoran bogga.');window.open(`https://wa.me/${phone}?text=${encodeURIComponent(`Salaan TekZone, waxaan ahay ${d.name}. ${d.message} (Xiriir: ${d.contact})`)}`,'_blank','noopener');toast('Farriinta WhatsApp ayaa la diyaariyay.')});
const review=document.getElementById('review-form');review?.addEventListener('submit',async e=>{e.preventDefault();try{await api('/reviews',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(review)))});toast('Qiimeynta waa la diray.');loadProduct(location.hash.split('/')[2])}catch(err){toast(err.message)}})}
async function loadOrders(){const root=document.getElementById('orders-view');if(!state.token){root.innerHTML=pageTitle('Dalabyadayda')+`<div class="wrap empty"><h2>Gal akoonkaaga si aad u aragto dalabyada.</h2><a class="button" href="#/login">Gal</a></div>`;return}try{const list=await api('/orders/mine');root.innerHTML=pageTitle('Dalabyadayda',`${list.length} dalab`)+`<div class="wrap" style="padding:22px 0">${list.length?list.map(o=>`<div class="order-card"><div class="order-head"><div><b>${esc(o.orderNumber)}</b><p class="muted">${new Date(o.createdAt).toLocaleDateString()} • ${o.items.length} nooc</p></div><span class="status ${o.status}">${esc(o.status)}</span></div><div class="sum-row"><span>${o.items.map(i=>esc(i.name)+' × '+i.quantity).join(', ')}</span><b>${money(o.total)}</b></div></div>`).join(''):'<div class="empty"><h2>Weli dalab ma samayn.</h2><a class="button" href="#/shop">Eeg alaabta</a></div>'}</div>`}catch(e){toast(e.message)}}
async function loadWishlist(){const root=document.getElementById('wishlist-view');if(!state.token){root.innerHTML=pageTitle('Waxyaabaha aan jeclahay')+`<div class="wrap empty"><h2>Gal si aad u aragto liiskaaga.</h2><a class="button" href="#/login">Gal akoonka</a></div>`;return}try{const ps=await api('/wishlist');root.innerHTML=pageTitle('Waxyaabaha aan jeclahay')+`<div class="wrap section"><div class="product-grid">${ps.length?ps.map(productCard).join(''):'<div class="empty" style="grid-column:1/-1"><h2>Liiskaagu waa madhan yahay.</h2><a class="button" href="#/shop">Eeg alaabta</a></div>'}</div></div>`}catch(e){toast(e.message)}}

// Admin data views use live API results for all operational totals and records.
async function loadAdmin(tab){const root=document.getElementById('admin-content');if(!root)return;try{if(tab==='overview'){const s=await api('/admin/stats');root.innerHTML=`<h1>Guudmar</h1><p>Warbixinta dukaankaaga waqtigan.</p><div class="stat-grid">${[['Iibka guud',money(s.sales)],['Dalabyada',s.orders],['Alaabta',s.products],['Macaamiisha',s.customers],['Sugaya xaqiijin',s.pending],['La gaarsiiyay',s.delivered],['Alaab bakhaar yar',s.low]].map(([k,v])=>`<div class="stat"><small>${k}</small><strong>${v}</strong></div>`).join('')}</div>${adminCharts(s)}<h3>Dalabyadii ugu dambeeyay</h3>${ordersTable(s.recentOrders)}`;return}
if(tab==='products'){const d=await api('/products?limit=48');root.innerHTML=`<h1>Alaabta</h1><p>Maamul qiimaha, bakhaarka iyo faahfaahinta alaabta.</p><div class="admin-toolbar"><input id="admin-product-q" placeholder="Raadi alaab..." oninput="filterTable(this.value,'products-table')"><button class="button" onclick="productModal()">+ Ku dar alaab</button></div><div class="table-wrap"><table class="table" id="products-table"><thead><tr><th>Alaabta</th><th>SKU</th><th>Qaybta</th><th>Qiimaha</th><th>Bakhaar</th><th>Ficil</th></tr></thead><tbody>${d.items.map(p=>`<tr data-search="${esc((p.name+' '+p.sku+' '+p.brand).toLowerCase())}"><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td><td>${money(price(p))}</td><td>${p.stock}</td><td><button class="button light small" onclick="productModal('${p._id}')">Wax ka beddel</button> <button class="button danger small" onclick="deleteProduct('${p._id}')">Tirtir</button></td></tr>`).join('')}</tbody></table></div>`;return}
if(tab==='orders'){const d=await api('/orders');root.innerHTML=`<h1>Dalabyada</h1><p>La soco, xaqiiji iyo cusboonaysii dalabyada.</p><div class="admin-toolbar"><input placeholder="Raadi dalab, magac ama telefoon..." oninput="filterTable(this.value,'orders-table')"><select class="admin-select" style="width:auto" onchange="filterStatus(this.value)"><option>Dhammaan xaaladaha</option>${['Pending','Confirmed','Processing','Shipped','Delivered','Cancelled'].map(x=>`<option>${x}</option>`).join('')}</select></div>${ordersTable(d,'orders-table',true)}`;return}
if(tab==='categories'){const cs=await api('/categories');state.categories=cs;root.innerHTML=`<h1>Qaybaha</h1><p>Maamul qaybaha dukaanka.</p><div class="admin-toolbar"><input id="new-category" placeholder="Magaca qaybta"><button class="button" onclick="addCategory()">+ Ku dar qayb</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Magaca</th><th>Sharaxaad</th><th>Ficil</th></tr></thead><tbody>${cs.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.description||'—')}</td><td><button class="button light small" onclick="editCategory('${c._id}','${esc(c.name)}')">Wax ka beddel</button> <button class="button danger small" onclick="deleteCategory('${c._id}')">Tirtir</button></td></tr>`).join('')}</tbody></table></div>`;return}
if(tab==='customers'){const d=await api('/admin/customers');root.innerHTML=`<h1>Macaamiisha</h1><p>${d.length} macaamiil oo diiwaangashan.</p><div class="table-wrap"><table class="table"><thead><tr><th>Magaca</th><th>Email</th><th>Telefoon</th><th>Dalabyo</th><th>Ku biiray</th></tr></thead><tbody>${d.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email||'—')}</td><td>${esc(u.phone)}</td><td>${u.orders}</td><td>${new Date(u.createdAt).toLocaleDateString()}</td></tr>`).join('')}</tbody></table></div>`;return}
if(tab==='inventory'){const d=await api('/admin/inventory');root.innerHTML=`<h1>Maamulka bakhaarka</h1><p>Alaab bakhaarkeedu gaaray 5 ama ka yar waa digniin.</p><div class="table-wrap"><table class="table"><thead><tr><th>Alaabta</th><th>SKU</th><th>Qaybta</th><th>Kaydka</th><th>Iibmay</th><th>Xaalad</th></tr></thead><tbody>${d.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.sku)}</td><td>${esc(p.category)}</td><td>${p.stock}</td><td>${p.sold||0}</td><td><span class="status ${p.stock===0?'Cancelled':''}">${p.stock===0?'Out of Stock':p.stock<=5?'Low Stock':'Bakhaar fiican'}</span></td></tr>`).join('')}</tbody></table></div>`;return}
if(tab==='reviews'){const d=await api('/reviews');root.innerHTML=`<h1>Qiimeynta</h1><p>Qiimeynta alaabta ee macaamiisha.</p><div class="table-wrap"><table class="table"><thead><tr><th>Macaamil</th><th>Alaabta</th><th>Qiimeyn</th><th>Faallo</th><th>Ficil</th></tr></thead><tbody>${d.map(r=>`<tr><td>${esc(r.user?.name||'')}</td><td>${esc(r.product?.name||'')}</td><td>${'★'.repeat(r.rating)}</td><td>${esc(r.comment)}</td><td><button class="button danger small" onclick="deleteReview('${r._id}')">Tirtir</button></td></tr>`).join('')}</tbody></table></div>`;return}
if(tab==='settings'){const s=await api('/settings');root.innerHTML=`<h1>Dejinta dukaanka</h1><p>Macluumaadka dukaanka iyo kharashka gaarsiinta.</p><form id="settings-form" class="panel" style="max-width:700px"><div class="form-grid">${[['storeName','Magaca dukaanka'],['phone','Telefoon'],['whatsapp','WhatsApp'],['email','Email'],['address','Cinwaan'],['deliveryFee','Kharashka gaarsiinta (USD)'],['currency','Lacagta'],['description','Sharaxaad']].map(([k,l])=>`<div class="field ${k==='description'||k==='address'?'full':''}"><label>${l}</label><input name="${k}" value="${esc(s[k]||'')}" ${k==='deliveryFee'?'type="number" min="0"':''}></div>`).join('')}</div><button class="button" style="margin-top:15px">Kaydi dejinta</button></form>`;root.querySelector('#settings-form').onsubmit=async e=>{e.preventDefault();try{await api('/settings',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.settings=await api('/settings');toast('Dejinta waa la kaydiyay.')}catch(x){toast(x.message)}};return}
}catch(e){root.innerHTML=`<div class="empty"><h2>${esc(e.message)}</h2></div>`;if(e.message.includes('gal akoon'))setTimeout(()=>href('login'),700)}}
function adminCharts(s){const max=Math.max(1,...s.salesByMonth.map(x=>x.sales));const bars=s.salesByMonth.map(x=>`<div title="${esc(x._id)}: ${money(x.sales)}" style="flex:1;display:flex;flex-direction:column;justify-content:end;align-items:center;height:145px;gap:7px"><span style="font-size:9px;color:#667085">${x.orders}</span><i style="height:${Math.max(4,x.sales/max*100)}%;width:min(26px,65%);background:#155eef;border-radius:4px 4px 0 0"></i><small style="font-size:9px;color:#667085">${esc(x._id.slice(5))}</small></div>`).join('');const cats=s.productsByCategory.map(x=>`<div style="display:grid;grid-template-columns:105px 1fr 26px;align-items:center;gap:8px;margin:10px 0;font-size:10px"><span>${esc(x._id)}</span><i style="height:8px;background:#e9eef8;border-radius:5px;overflow:hidden"><b style="display:block;height:100%;width:${Math.max(6,x.count/Math.max(1,...s.productsByCategory.map(y=>y.count))*100)}%;background:#1b9a78;border-radius:5px"></b></i><b>${x.count}</b></div>`).join('');return `<div style="display:grid;grid-template-columns:1.3fr 1fr;gap:13px;margin:15px 0"><section class="panel"><h3> iibka &amp; dalabyada · 6 bilood </h3><div style="height:165px;display:flex;align-items:stretch;gap:10px;border-bottom:1px solid #e7eaf0">${bars||'<span class="muted">Xogtu marka dalabyo yimaadaan ayay muuqanaysaa.</span>'}</div><small class="muted">Tiir kasta: lacagta iibka • tirada dusha ku qoran waa dalabyada</small></section><section class="panel"><h3>Alaabta qayb kasta</h3>${cats||'<p class="muted">Alaab weli lama diiwaangelin.</p>'}</section></div>`}
function ordersTable(data,id='orders-table',editable=false){return `<div class="table-wrap"><table class="table" id="${id}"><thead><tr><th>Lambarka</th><th>Macaamil</th><th>Taariikh</th><th>Wadarta</th><th>Xaalad</th>${editable?'<th>Wax ka beddel</th>':''}</tr></thead><tbody>${data.map(o=>`<tr data-status="${o.status}" data-search="${esc((o.orderNumber+' '+o.customerInfo?.name+' '+o.customerInfo?.phone).toLowerCase())}"><td>${esc(o.orderNumber)}</td><td>${esc(o.customerInfo?.name||'')}</td><td>${new Date(o.createdAt).toLocaleDateString()}</td><td>${money(o.total)}</td><td><span class="status ${o.status}">${esc(o.status)}</span></td>${editable?`<td><select class="admin-select" style="width:auto;padding:6px" onchange="updateStatus('${o._id}',this.value)">${['Pending','Confirmed','Processing','Shipped','Delivered','Cancelled'].map(x=>`<option ${x===o.status?'selected':''}>${x}</option>`).join('')}</select></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function filterTable(q,id){document.querySelectorAll('#'+id+' tbody tr').forEach(r=>r.style.display=(r.dataset.search||'').includes(q.toLowerCase())?'':'none')}
function filterStatus(s){document.querySelectorAll('#orders-table tbody tr').forEach(r=>r.style.display=s==='Dhammaan xaaladaha'||r.dataset.status===s?'':'none')}
async function updateStatus(id,status){try{await api('/orders/'+id+'/status',{method:'PUT',body:JSON.stringify({status})});toast('Xaaladda dalabka waa la cusboonaysiiyay.');loadAdmin('orders')}catch(e){toast(e.message);loadAdmin('orders')}}
function modal(html){const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal">${html}</div>`;b.addEventListener('click',e=>{if(e.target===b)b.remove()});document.body.append(b);return b}
async function productModal(id){let p={name:'',sku:'',category:'Mobile Phones',brand:'',price:'',discountPrice:'',stock:0,description:'',specifications:{},images:[],featured:false,bestSeller:false,newArrival:true};if(id)try{p=(await api('/products/'+id)).product}catch(e){return toast(e.message)}if(!state.categories.length)try{state.categories=await api('/categories')}catch{}const b=modal(`<h2>${id?'Wax ka beddel alaab':'Ku dar alaab cusub'}</h2><form id="product-form"><div class="form-grid"><div class="field"><label>Magaca</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>SKU</label><input name="sku" value="${esc(p.sku)}" required></div><div class="field"><label>Qaybta</label><select name="category">${(state.categories.length?state.categories:[{name:p.category}]).map(c=>`<option ${c.name===p.category?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Summad / Brand</label><input name="brand" value="${esc(p.brand)}"></div><div class="field"><label>Qiimaha USD</label><input name="price" type="number" min="0" step=".01" value="${p.price}" required></div><div class="field"><label>Qiimo dhimis</label><input name="discountPrice" type="number" min="0" step=".01" value="${p.discountPrice||''}"></div><div class="field"><label>Tirada bakhaarka</label><input name="stock" type="number" min="0" value="${p.stock}" required></div><div class="field"><label>Sawirro (URL, kala saar comma)</label><input name="images" value="${esc((p.images||[]).join(', '))}"><input id="product-image-files" type="file" accept="image/jpeg,image/png,image/webp,image/gif" multiple style="margin-top:7px"></div><div class="field full"><label>Sharaxaad</label><textarea name="description">${esc(p.description)}</textarea></div><div class="field"><label><input name="featured" type="checkbox" ${p.featured?'checked':''}> Alaab la xushay</label></div><div class="field"><label><input name="bestSeller" type="checkbox" ${p.bestSeller?'checked':''}> Ugu iib badan</label></div><div class="field"><label><input name="newArrival" type="checkbox" ${p.newArrival?'checked':''}> Alaab cusub</label></div></div><div class="modal-actions"><button type="button" class="button light" onclick="this.closest('.modal-backdrop').remove()">Jooji</button><button class="button">Kaydi alaabta</button></div></form>`);b.querySelector('#product-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.price=Number(data.price);data.discountPrice=data.discountPrice?Number(data.discountPrice):null;data.stock=Number(data.stock);data.images=data.images?data.images.split(',').map(x=>x.trim()).filter(Boolean):[];data.specifications=p.specifications||{};for(const k of ['featured','bestSeller','newArrival'])data[k]=f.has(k);try{const files=Array.from(b.querySelector('#product-image-files').files);if(files.length){const fd=new FormData();files.forEach(file=>fd.append('images',file));const uploadResponse=await fetch(API+'/uploads',{method:'POST',headers:{Authorization:'Bearer '+state.token},body:fd});const uploaded=await uploadResponse.json();if(!uploadResponse.ok)throw Error(uploaded.message||'Sawirrada lama soo gelin.');data.images.push(...uploaded.images)}await api('/products'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(data)});b.remove();toast('Alaabta waa la kaydiyay.');loadAdmin('products')}catch(x){toast(x.message)}}}
async function deleteProduct(id){if(!confirm('Ma hubtaa inaad tirtirayso alaabtan?'))return;try{await api('/products/'+id,{method:'DELETE'});toast('Alaabta waa la tirtiray.');loadAdmin('products')}catch(e){toast(e.message)}}
async function addCategory(){const name=document.getElementById('new-category').value.trim();if(!name)return;try{await api('/categories',{method:'POST',body:JSON.stringify({name})});toast('Qaybta waa lagu daray.');loadAdmin('categories')}catch(e){toast(e.message)}}
async function editCategory(id,name){const v=prompt('Magaca cusub:',name);if(!v||v===name)return;try{await api('/categories/'+id,{method:'PUT',body:JSON.stringify({name:v})});toast('Qaybta waa la cusboonaysiiyay.');loadAdmin('categories')}catch(e){toast(e.message)}}
async function deleteCategory(id){if(!confirm('Ma hubtaa inaad tirtirayso qaybtaan?'))return;try{await api('/categories/'+id,{method:'DELETE'});toast('Qaybta waa la tirtiray.');loadAdmin('categories')}catch(e){toast(e.message)}}
async function deleteReview(id){if(!confirm('Tirtir qiimeyntan?'))return;try{await api('/reviews/'+id,{method:'DELETE'});toast('Qiimeynta waa la tirtiray.');loadAdmin('reviews')}catch(e){toast(e.message)}}
window.addEventListener('hashchange',render);window.addEventListener('keydown',e=>{if(e.key==='Enter'&&document.activeElement?.id==='global-search')searchNow()});
(async()=>{try{const [s,c]=await Promise.all([api('/settings'),api('/categories')]);state.settings=s;state.categories=c;await loadProducts()}catch{}await render()})();
